# Acrescentado em 2026-11-20, a partir de Luciano Carlos Cunha, Razões para ajudar: o sofrimento dos animais selvagens e suas
# implicações éticas (Appris, 2022): o que cada teoria diz sobre ajudar os animais selvagens. Cada entrada vira uma seção nova
# de "mais", e o livro entra nas fontes. As posições contestadas de Cunha aparecem como debate, com quem discorda.
RAZOES = ('Razões para ajudar: o sofrimento dos animais selvagens e suas implicações éticas', 'https://senciencia.org/wp-content/uploads/2026/02/luciano-carlos-cunha-razoes-para-ajudar.pdf')
_GROFF = ('Does suffering dominate enjoyment in the animal kingdom? An update to welfare biology', 'https://doi.org/10.1007/s10539-019-9692-0')
_BROWNING = ('Positive Wild Animal Welfare', 'https://doi.org/10.1007/s10539-023-09901-5')
SELVAGENS = {
 'ambientalismo': ('Ajudar os animais selvagens: onde o conflito aparece', [
    'É no caso dos animais selvagens que a diferença entre ambientalismo e defesa dos animais fica mais nítida. O filósofo Luciano Carlos Cunha, em Razões para ajudar (2022), separa três famílias de ambientalismo pelo que elas valorizam diretamente: o holismo, que valoriza totalidades como espécies e ecossistemas (o ecocentrismo é a versão centrada nos ecossistemas); o naturocentrismo, que valoriza o que tem origem natural, não humana; e o biocentrismo, que valoriza o bem de cada organismo vivo. Ele observa que o biocentrismo, levado a sério, pediria mais ajuda aos animais selvagens, e não menos: se o bem de cada organismo conta, a dinâmica populacional, em que quase todos morrem logo depois de nascer, também é um problema para ele (N15).',
    'Mesmo para quem dá valor próprio a espécies e ecossistemas, a conclusão "não ajude" não se segue. Primeiro, um valor ambiental só bloquearia toda ajuda se funcionasse como um trunfo absoluto, e não só como um peso maior; e muitas ajudas, como vacinar contra a raiva ou tirar um animal atolado na lama, não afetam meta ambiental nenhuma. Segundo, se o valor ambiental se soma ao bem dos seres sencientes, reduzir o sofrimento também aumenta o valor total. Terceiro, os próprios ambientalistas já limitam suas metas pelos interesses básicos dos humanos: ninguém propõe deixar de tratar a malária de uma comunidade que vive na floresta para preservar o curso natural das coisas. Sem especismo, o mesmo limite vale para os outros animais (N3, N9).',
    'Cunha vai além e sustenta que as visões ambientalistas pluralistas, que dizem dar algum valor aos indivíduos sencientes, acabam sendo antropocêntricas na prática, porque aprovam o abate de animais por metas ambientais e nunca o de humanos. É uma tese dele, que os pluralistas rejeitam. Ele também lembra que a ecologia descreve o que acontece na natureza e não diz o que devemos fazer: quem tira dela uma norma é que confunde as áreas.',
    'O ponto de conflito mais forte é a expansão das áreas naturais. Cunha, assim como Oscar Horta e Brian Tomasik, defende não expandir nem recriar áreas naturais, por exemplo por reflorestamento ou renaturalização, porque isso multiplicaria o nascimento de animais que têm milhares de filhotes, quase todos condenados a morrer cedo. Ele não propõe destruir os habitats que existem, e recomenda não começar a conversa por esse ponto com quem ainda não conhece o problema. A tese é contestada. Conservacionistas e políticas climáticas defendem o reflorestamento, inclusive para retirar carbono da atmosfera; Cunha responde que há outros meios contra a mudança do clima, como a eficiência energética e as energias renováveis. Organizações dedicadas aos animais selvagens, como a Wild Animal Initiative, concentram-se por ora em pesquisa sobre o bem-estar deles. E a tese depende de um saldo de bem-estar na natureza que é incerto: Zach Groff e Yew-Kwang Ng (2019) concluíram que ele pode pender para os dois lados, e Heather Browning e Walter Veit (2023) defendem que pode ser positivo (N1, N16).',
    'J. Baird Callicott, que desenvolveu a ética da terra a partir de Aldo Leopold, está do outro lado desse debate. Em "Animal Liberation: A Triangular Affair" (1980), opôs a ética da terra holista à defesa dos animais como indivíduos. Em "Animal Liberation and Environmental Ethics: Back Together Again" (1988), aproximou as duas ao tratar os animais domesticados como membros de uma comunidade mista com os humanos, mas continuou negando aos animais selvagens o direito à vida e tratando-os como partes das metas ambientais. Por isso ele não aparece na lista abaixo, de quem defende os animais a partir desta teoria (A10).']),
 'utilitarismo': ('Os animais selvagens no cálculo utilitarista', [
    'Se o que importa é o sofrimento, e não quem o causou, o utilitarismo não tem como ignorar o sofrimento dos animais selvagens, que vem sobretudo da fome, da doença, do parasitismo e da morte logo depois do nascimento. A tese da equivalência, defendida por James Rachels e, com ressalvas, por Singer, diz que não há diferença intrínseca entre causar um dano evitável e deixar que aconteça, se todo o resto for igual (N6). Singer admite diferenças que costumam acompanhar a distinção, como a motivação e a certeza do resultado, e por isso não condena a omissão como se fosse o próprio ato; mas acha que essas diferenças não bastam para torná-la aceitável. E a utilidade marginal decrescente faz com que o mesmo recurso produza mais bem quando chega a quem está pior, o que fortalece a razão para ajudar animais em situações extremas.',
    'O próprio Singer foi cético: em Libertação Animal, escreveu que as tentativas de mudar ecossistemas em larga escala tendem a fazer mais mal do que bem. Segundo Luciano Carlos Cunha, em Razões para ajudar (2022), ele mudou de posição numa palestra de 2016, passando a tratar o tema como questão ética importante e a apoiar a pesquisa. Também se pergunta se a teoria levaria a medidas drásticas, como matar animais para evitar que se reproduzam. Cunha responde que, mesmo para quem só olha as consequências, há boas razões para uma regra geral contra matar: a matança reforça a ideia de que os animais são descartáveis e confunde a ajuda com o manejo ambiental, com efeitos piores no longo prazo (N17, N11).',
    'Há uma divergência interna. Utilitaristas clássicos somam bem-estar e sofrimento; autores centrados no sofrimento, como Brian Tomasik e Magnus Vinding, dão prioridade a reduzi-lo. A diferença pesa aqui, porque o saldo de bem-estar na natureza é incerto (Groff e Ng, 2019) e pode até ser positivo (Browning e Veit, 2023). Cunha argumenta que, mesmo com saldo positivo, continuaria havendo um número enorme de vidas que vão muito mal, e que a razão para ajudar essas vidas não depende do saldo (N1).']),
 'contratualismo': ('O contrato e os animais selvagens', [
    'Mesmo sem incluir os animais, nenhum contratante racional aprovaria uma proibição total de intervir na natureza, porque intervir é necessário para a própria sobrevivência. Isso já mostra que "não mexer na natureza" não pode ser um princípio do contrato (N9).',
    'Sob o véu de Rowlands, que esconde também a espécie, as partes não sabem se nasceriam humanas ou como um dos animais que vivem fora do controle humano. Luciano Carlos Cunha, em Razões para ajudar (2022), argumenta que elas escolheriam ajudar quem está em perigo independentemente de o dano ter origem humana ou natural, e rejeitariam limitar a ajuda a quem pode retribuir. Como os animais selvagens são astronomicamente mais numerosos que os humanos, a chance de nascer como um deles pesaria muito na escolha (N6, N7).']),
 'deontologia': ('Direitos e animais selvagens', [
    'Tom Regan defendeu que, diante dos animais selvagens, o dever é "deixá-los ser": os direitos proíbem prejudicá-los, mas não exigem protegê-los de predadores e doenças. Gary Francione vai na mesma direção ao admitir só direitos negativos. Luciano Carlos Cunha, em Razões para ajudar (2022), contesta os dois. A acusação de paternalismo não se aplica, porque nada indica que os animais prefiram não ser ajudados: fugir de quem se aproxima mostra medo de uma ameaça, e não recusa da ajuda. E o argumento de Regan de que os animais selvagens têm capacidade de escapar dos perigos passa da espécie, que de fato sobrevive, para os indivíduos, que na maioria são filhotes e não sobrevivem (N8, N4).',
    'Outros autores dentro da tradição dos direitos defendem deveres positivos. Henry Shue, em Basic Rights (1980), sustenta que os direitos básicos à segurança e à subsistência exigem também proteção e ajuda de outros. Kyle Johannsen e Jeff McMahan, que aceitam restrições deontológicas, defendem ajudar os animais selvagens. E Cunha observa que a deontologia limita os meios de ajudar, como a proibição de matar, mas não sustenta uma proibição absoluta de intervir: a máxima "nunca intervir na natureza" não poderia valer como lei universal, porque nenhum agente sobrevive sem intervir (N6, N13).',
    'Há ainda uma tensão. Quem rejeita ajudar por respeito a direitos às vezes apela às consequências, dizendo que impedir a predação causaria uma explosão de presas e mais mortes por fome. Mas uma teoria que nega que as consequências decidam o certo não pode recorrer a elas só neste caso. A divergência também corre no sentido inverso: Cunha considera absurdo ver a exploração como errada em si, independentemente de como afeta os animais, e abolicionistas e seguidores de Regan discordam dele nesse ponto (N17).']),
 'libertarianismo': ('E os animais selvagens?', [
    'Uma teoria só de direitos negativos diz que não devemos agredir, mas não obriga ninguém a socorrer. Rainer Ebert e Tibor Machan, em "Innocent Threats and the Moral Problem of Carnivorous Animals" (2012), discutem o que uma teoria dos direitos animais implica diante da predação e apontam, como uma das saídas, uma versão baseada em direitos negativos. Luciano Carlos Cunha, em Razões para ajudar (2022), responde que, mesmo aceitando só direitos negativos, ajudar os animais selvagens continuaria permitido e louvável, e que, se o que justifica os direitos negativos são os interesses de quem pode ser prejudicado, os mesmos interesses justificam também alguma assistência. Para um libertário, essa ajuda pode vir de doações e de ação voluntária, sem depender do Estado (N6, N13).']),
 'igualitarismo': ('Os animais selvagens: quem está pior', [
    'Os animais selvagens são um caso central para o igualitarismo e o prioritarismo. A maioria dos animais nasce em espécies que têm centenas, milhares ou milhões de filhotes, e quase todos morrem pouco depois de nascer, de fome, frio, doença ou predação. Se a razão para ajudar fica mais forte quanto pior alguém está, essas vidas estão entre as que mais pedem ajuda (N1).',
    'A ideia de que desvantagens que ninguém escolheu são injustas, discutida por autores como Nils Holtug e Kasper Lippert-Rasmussen, também responde à imagem de uma "natureza justa", em que cada animal teria armas para escapar. Luciano Carlos Cunha, em Razões para ajudar (2022), observa que ter capacidades parecidas não garante a mesma sorte, e que os predadores escolhem justamente os mais fracos (N4).',
    'Ele também responde a quem diz que o bem-estar na natureza pode ter saldo positivo, como defendem Groff e Ng (2019) e Browning e Veit (2023). Para teorias igualitaristas, prioritaristas e suficientistas, um saldo positivo agregado não anula as razões para ajudar quem está muito mal, assim como a riqueza de alguns não diminui o peso da fome de outros.']),
 'cuidado': ('O cuidado e os animais selvagens', [
    'Há uma versão da ética do cuidado que limita os deveres aos próximos e é usada contra ajudar os animais selvagens. Grace Clement, em "The Ethic of Care and the Problem of Wild Animals" (2003), aplica o cuidado contra a intervenção na natureza, e Clare Palmer, em Animal Ethics in Context (2010), defende uma intuição de "deixar estar" (laissez-faire) para os animais selvagens: não haveria, em geral, dever de assisti-los, porque não temos com eles a relação que temos com os domesticados (N7).',
    'Luciano Carlos Cunha, em Razões para ajudar (2022), e Catia Faria, em "Disentangling Obligations of Assistance" (2015), respondem que a relação não decide sozinha quem merece ajuda. Faria imagina três opções: apertar um botão que imuniza contra o câncer todos os humanos, apertar outro que imuniza só as pessoas próximas de nós, ou não apertar nenhum. Quase ninguém acha aceitável escolher o segundo. E quem usa a falta de relação para não ajudar os selvagens perde o argumento contra a exploração, porque também não temos relação com os animais de granja que compramos (K2).']),
 'virtudes': ('Os animais selvagens: a objeção de Hursthouse', [
    'Rosalind Hursthouse, em "Virtue Ethics and the Treatment of Animals" (2011), reconhece que na vida dos animais selvagens costuma predominar o sofrimento, mas rejeita intervir para ajudá-los: isso destruiria as formas de vida características de cada espécie, viria da aplicação de princípios gerais, de que a ética das virtudes desconfia, e imporia valores antropocêntricos.',
    'Luciano Carlos Cunha, em Razões para ajudar (2022), responde que a regra "rejeite princípios gerais" já é um princípio geral, e que a conclusão de Hursthouse também depende de um: o de preservar as formas de vida características, por pior que sejam para quem as vive. Ninguém aplica esse princípio a humanos: tratamos doenças que também fazem parte da vida da espécie. Ele acrescenta que "nunca intervir na natureza" não poderia ser uma virtude, porque impediria cultivar qualquer outra, e que uma pessoa compassiva não ficaria indiferente a um sofrimento imenso só por não o ter causado (N6, N8).']),
 'capacidades': ('Os animais selvagens e o florescimento', [
    'Luciano Carlos Cunha, em Razões para ajudar (2022), destaca um ponto em que Nussbaum concorda com os defensores da ajuda: em Frontiers of Justice, ela separa a culpa do predador da questão de prevenir o dano à presa. O leão não é culpado de nada, mas isso não decide se devemos proteger a gazela, como observaram também Steve Sapontzis e Tyler Cowen (F4).',
    'Ele aponta ainda uma tensão na ideia de florescer segundo a própria natureza, defendida em versões diferentes por Thomas Hurka e por Jennifer Everett. Se a natureza de uma espécie faz quase todos os seus filhotes morrerem de fome logo depois de nascer, deixá-los entregues a isso não é o que há de melhor para eles; é uma razão para mudar essas condições, como fazemos com doenças que também são naturais (N2, N8).']),
 'liberalismo': ('Zoopolis e os animais selvagens', [
    'Em Zoopolis, Sue Donaldson e Will Kymlicka tratam as comunidades de animais selvagens como soberanas, com direito a se governar sem interferência, o que limita a intervenção a casos que não ameacem essa autonomia. Alasdair Cochrane, em "Cosmozoopolis" (2013), e Oscar Horta, em "Zoopolis, Interventions and the State of Nature" (2013), contestam. Para Horta, a situação dos animais selvagens se parece com uma catástrofe humanitária. Ele, Catia Faria e Luciano Carlos Cunha descrevem a maioria das populações selvagens como "Estados falidos", incapazes de garantir o bem-estar dos seus membros, já que quase todos morrem logo depois de nascer. Faria vai além: se a soberania se justifica pelos interesses dos indivíduos, ela pede um "melhoramento ambiental", isto é, mudar as condições naturais quando isso melhora o bem-estar dos animais (N8).',
    'Há também a questão do paternalismo, cara ao liberalismo. Cunha, em Razões para ajudar (2022), observa que não há sinal de que os animais prefiram não ser ajudados: quando fogem de quem tenta socorrê-los, mostram medo de uma ameaça, e não recusa da ajuda. E muitas ajudas, como água, comida ou vacina por isca, não tiram a liberdade de ninguém (N1).']),
 'comunitarismo': ('A comunidade e os animais selvagens', [
    'O critério do território, segundo o qual os domésticos são "dos nossos" e os selvagens pertencem a outra comunidade, tem uma base comunitarista: a comunidade mista de J. Baird Callicott, que dá aos domesticados os direitos de membros e nega aos selvagens até o direito à vida. Luciano Carlos Cunha, em Razões para ajudar (2022), observa que o critério só é aplicado quando as vítimas não são humanas: quase ninguém acha que se deve deixar de tratar a malária de povos que vivem na floresta porque eles pertenceriam a outro "território". E a dívida histórica com os domesticados daria, no máximo, prioridade a eles, e não um motivo para excluir os selvagens (N7).']),
 'altruismo-eficaz': ('Os animais selvagens como prioridade', [
    'Pelos critérios de escala, negligência e tratabilidade, o sofrimento dos animais selvagens é um caso extremo. As estimativas de Brian Tomasik, que ele mesmo trata como muito incertas, falam em algo entre cem quatrilhões e dez quintilhões de artrópodes terrestres vivos ao mesmo tempo, além de dezenas a centenas de trilhões de peixes, e quase nenhum recurso é dedicado a eles. Luciano Carlos Cunha, em Razões para ajudar (2022), argumenta que, mesmo dando a cada humano um peso dez vezes maior, a escala obrigaria a investir mais nos animais.',
    'A tratabilidade é o ponto mais discutido. Cunha examina as objeções de eficiência: que só valeria agir em larga escala, que o efeito seria de curto prazo, que seria "enxugar gelo" porque os animais voltam a se reproduzir, e que gastaria recursos de outras causas. Ele responde que esterilizar metade de uma população já evita metade dos nascimentos de filhotes que morreriam logo, que pesquisa e divulgação preparam ações maiores, e que se deve decidir pelo impacto esperado, e não pelo pior cenário. Também alerta para o viés da proporção: julgar uma causa pela porcentagem do problema que se consegue resolver, e não pela quantidade de dano evitado. Mas ele admite que faltam comparações de custo-efetividade entre essa causa e outras (N12, N13).']),
 'lei-natural': ('Intenção, efeito colateral e os animais selvagens', [
    'A doutrina do duplo efeito, que vem da tradição tomista, distingue o mal que se causa de propósito do mal que se prevê como efeito colateral. Luciano Carlos Cunha, em Razões para ajudar (2022), discute uma ideia parecida, que ele chama de requerimento da intenção: só responderíamos pelo dano que pretendemos causar, e não pelo sofrimento que deixamos acontecer. Ele responde com um exemplo: quem deixa uma criança se afogar para não interromper o programa de televisão não pretendia a morte dela, e nem por isso fica inocente. A distinção pode limitar os meios de ajudar, como a proibição de matar um animal para salvar outros, mas não mostra que não haja razão para ajudar (N6).']),
 'religiao': ('A natureza como obra de um criador bom', [
    'Uma objeção comum diz que a natureza não erra, ou que a ordem natural foi feita por um criador e não deve ser corrigida. Luciano Carlos Cunha, em Razões para ajudar (2022), responde que, mesmo admitindo um criador, disso não se segue que tudo o que acontece na natureza seja bom: seria preciso mostrar que esse criador é bom e que quer exatamente esse resultado. Ele propõe imaginar alguém perverso que quisesse maximizar o sofrimento: criaria seres com tantos filhotes que quase todos morressem de fome logo depois de nascer, e outros que precisassem comer suas presas ainda vivas. O resultado se pareceria muito com a natureza que conhecemos. Para as tradições religiosas, isso é parte do problema do mal, e não uma razão para cruzar os braços: elas já aceitam curar doenças e socorrer vítimas de enchentes e secas, e a misericórdia que ensinam não depende de o sofrimento ter sido causado por humanos (N2).']),
 'relativismo': ('Sofrimento é só uma preferência?', [
    'Uma variante cética diz que achar o sofrimento ruim é só uma preferência subjetiva, e que não temos como saber se ele é mesmo ruim. Luciano Carlos Cunha, em Razões para ajudar (2022), responde que, nesse caso, o juízo é sobre a própria experiência, e não sobre um objeto do mundo externo: sofrer é, por definição, viver algo como negativo, e uma experiência que não fosse negativa não seria sofrimento. Isso vale para quem a vive, humano ou não, e venha ela de uma pessoa ou de uma doença. Quem aceita esse ponto para si não tem razão para negá-lo aos animais selvagens (N2).']),
 'egoismo-objetivismo': ('O egoísmo e a presa', [
    'O egoísmo aparece de forma indireta no debate sobre a predação. Diz-se às vezes que a presa pode se defender, mas que ninguém mais pode defendê-la, porque cada um só teria o direito de proteger a si mesmo. Luciano Carlos Cunha, em Razões para ajudar (2022), observa que isso pressupõe um egoísmo obrigatório, em que seria errado se preocupar com outros, o que nem os egoístas éticos costumam defender: a versão mais comum diz que é permitido cuidar só de si, e não que é proibido cuidar dos outros. E, como argumenta o filósofo Stuart Rachels, a razão que tenho para acabar com a minha dor vem de a dor ser ruim, e não de ela ser minha; a mesma razão vale para a dor de qualquer outro (N17, N4).']),
 'humanismo': ('O teste humano', [
    'Uma ferramenta que atravessa o debate sobre os animais selvagens é o teste humano: perguntar o que diríamos se as vítimas fossem humanas. Se crianças humanas nascessem aos milhares para quase todas morrerem de fome ou devoradas vivas logo depois, ninguém diria que é a ordem natural e que não devemos interferir; e, se humanos fossem presas habituais de um predador, ninguém hesitaria em protegê-los. Luciano Carlos Cunha, em Razões para ajudar (2022), usa esse teste em todo o livro, e ele é a aplicação direta da razão e da imparcialidade que o humanismo defende (N2, N17).',
    'O teste também expõe uma ironia. Pela definição usual de espécie invasora, a de uma espécie que não é nativa do lugar e ameaça metas ambientais, os humanos seriam uma espécie invasora em quase todo o planeta. Quase ninguém conclui daí que seria aceitável matá-los para proteger um ecossistema, o que mostra que o critério só é aplicado aos outros animais (A10, H19).']),
}
# Códigos acrescentados a "Veja também": os que o texto da seção cita, inclusive os novos N22-N27.
SELVAGENS_LIGA = {'ambientalismo': ['N15', 'N16', 'N1'], 'utilitarismo': ['N1', 'N6', 'N17', 'N11'], 'contratualismo': ['N6', 'N9', 'N7'], 'deontologia': ['N8', 'N4', 'N6', 'N13', 'N17'],
                  'libertarianismo': ['N6', 'N13'], 'igualitarismo': ['N1', 'N4'], 'cuidado': ['N7', 'N6'], 'virtudes': ['N6', 'N8'], 'capacidades': ['N2'], 'liberalismo': ['N8'],
                  'comunitarismo': ['N7', 'N6'], 'altruismo-eficaz': ['N12', 'N13'], 'lei-natural': ['N6'], 'religiao': ['N2'], 'relativismo': ['N2'],
                  'egoismo-objetivismo': ['N17', 'N4'], 'humanismo': ['N2', 'N17']}
# Fontes extras por teoria. Os títulos são os originais, iguais nas duas línguas.
SELVAGENS_FONTES = {'ambientalismo': [_GROFF, _BROWNING, ('Intuitions Gone Astray: between Implausibility and Speciesism', 'https://doi.org/10.7358/rela-2015-001-paez')],
                    'utilitarismo': [_GROFF, _BROWNING, ('Predation (Ethics and Animals, 1984)', 'https://doi.org/10.15368/ea.1984v5n2.1'), ('Policing Nature', 'https://doi.org/10.5840/enviroethics200325231')],
                    'deontologia': [('The Moral Problem of Predation', 'https://doi.org/10.4324/9780203154410-18'), ('The Predation Argument', 'https://digitalcommons.calpoly.edu/bts/vol13/iss5/3')],
                    'libertarianismo': [('Innocent Threats and the Moral Problem of Carnivorous Animals', 'https://doi.org/10.1111/j.1468-5930.2012.00561.x')],
                    'igualitarismo': [_GROFF, _BROWNING],
                    'cuidado': [('The Ethic of Care and the Problem of Wild Animals', 'https://doi.org/10.15368/bts.2003v13n3.2'), ('Disentangling Obligations of Assistance', 'https://doi.org/10.7358/rela-2015-002-fari')],
                    'liberalismo': [('Zoopolis, Interventions and the State of Nature', 'https://www.raco.cat/index.php/LEAP/article/view/294784'), ('Cosmozoopolis: The Case Against Group-Differentiated Animal Rights', None)],
                    'comunitarismo': [('The Duty to Aid Nonhuman Animals in Dire Need', 'https://doi.org/10.1111/j.1468-5930.2006.00358.x')]}

def aplicar_selvagens(teorias, secoes, livro, chave=lambda t: t['s']):
    """Acrescenta a seção sobre animais selvagens e as fontes (e, na primeira chamada, os códigos de "Veja também").
    A versão em inglês chama de novo com as próprias seções sobre o dicionário POLITICAS."""
    for t in teorias:
        s = chave(t)
        if s not in secoes: continue
        t['mais'] = list(t.get('mais', [])) + [secoes[s]]
        if 'liga' in t: t['liga'] = list(dict.fromkeys(t['liga'] + SELVAGENS_LIGA.get(s, [])))
        if 'fontes' in t: t['fontes'] = list(dict.fromkeys(list(t['fontes']) + [livro] + SELVAGENS_FONTES.get(s, [])))

aplicar_selvagens(TEORIAS, SELVAGENS, RAZOES)
